import React from 'react';
import Svg, { Path, Rect } from 'react-native-svg';
import { scaleSizeW } from '@/utils/screenUtils';

interface IconProps {
  size?: number;
  color?: string;
}

interface P {
  d: string;
  fill: string;
}

function renderIcon(paths: P[], size: number, viewBox = '0 0 20 20') {
  const s = scaleSizeW(size);
  return (
    <Svg width={s} height={s} viewBox={viewBox} fill="none">
      {paths.map((p, i) => (
        <Path key={i} d={p.d} fill={p.fill} />
      ))}
    </Svg>
  );
}

